pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_map: serde_json::Map<String, serde_json::Value> = input.as_object().unwrap();
    let jobs = input_map
        .get("jobs")
        .unwrap()
        .as_array()
        .unwrap()
        .clone();
    let quantum = input_map
        .get("quantum")
        .unwrap()
        .as_i64()
        .unwrap()
        .try_into()
        .unwrap();

    let mut work = jobs.clone();
    let mut result = Vec::new();
    let mut job_idx = 0;

    while work.iter().any(|&w| w > 0) {
        let mut completed = Vec::new();
        let mut current_idx = 0;

        while current_idx < work.len() {
            if work[current_idx] > 0 {
                let work_to_do = (work[current_idx] as i64).min(quantum as i64) as usize;
                work[current_idx] -= work_to_do;
                if work[current_idx] == 0 {
                    completed.push(current_idx);
                }
            }
            current_idx += 1;
        }

        if completed.is_empty() {
            break;
        }

        // Sort by completion order: zero-work jobs first, then by index
        completed.sort_by(|a, b| {
            if work[*a] == 0 && work[*b] == 0 {
                a.cmp(b)
            } else if work[*a] == 0 {
                std::cmp::Ordering::Less
            } else if work[*b] == 0 {
                std::cmp::Ordering::Greater
            } else {
                a.cmp(b)
            }
        });

        result.extend(completed);
    }

    serde_json::json!(result)
}
